```json
{
  "screenability": {
    "status": "not_runnable",
    "ruleset": "register-screen/3",
    "proposal_revision": "<slug-or-digest>",
    "blockers": [{
      "code": "surface_undeclared",
      "gate": "robustness",
      "clears_on": ["amendment:surface_declared"]
    }]
  },
  "second_intake": {"disposition": "record_held"}
}
